### 1. `src/org/example/ConventionalVersion.groovy`

```groovy
package org.example

class ConventionalVersion implements Serializable {
    def steps
    ConventionalVersion(steps) { this.steps = steps }

    String bump(String fromVersion = '0.0.0') {
        def log = steps.sh(script: "git log --pretty=format:'%s' ${fromVersion}..HEAD", returnStdout: true).trim()
        def commits = log.split('\n')

        boolean hasMajor = commits.any { it =~ /^(?i)BREAKING CHANGE:|feat(\(.+\))?!:/ }
        boolean hasMinor = commits.any { it =~ /^(?i)feat(\(.+\))?:/ }
        boolean hasPatch = commits.any { it =~ /^(?i)fix(\(.+\))?:|chore:|docs:|refactor:/ }

        def parts = fromVersion.tokenize('.')
        int major = parts[0].toInteger()
        int minor = parts[1].toInteger()
        int patch = parts[2].toInteger()

        if (hasMajor)      return "${major + 1}.0.0"
        else if (hasMinor) return "${major}.${minor + 1}.0"
        else if (hasPatch) return "${major}.${minor}.${patch + 1}"
        return "${major}.${minor}.${patch}"
    }
}
```

### 2. `vars/bumpVersion.groovy`

```groovy
def call() {
    def versioner = new org.example.ConventionalVersion(this)
    def lastTag = sh(script: 'git describe --tags --abbrev=0 || echo "0.0.0"', returnStdout: true).trim()

    def newVersion = versioner.bump(lastTag)

    echo "Bumping version from ${lastTag} to ${newVersion} based on conventional commits"

    sh """
        git tag -a v${newVersion} -m "Release v${newVersion} (auto)"
        git push origin v${newVersion}
    """
    return newVersion
}
```

### 3. `vars/signArtifact.groovy`

```groovy
def call(String artifactPath, String keyCredentialId = 'gpg-signing-key') {
    withCredentials([string(credentialsId: keyCredentialId, variable: 'GPG_KEY')]) {
        sh """
            echo "\${GPG_KEY}" | gpg --batch --import -
            gpg --batch --yes --detach-sign --armor --local-user jenkins@ci.internal ${artifactPath}
        """
    }
