### 4. `vars/checkCredentialsHealth.groovy` (Safe version)

```groovy
import com.cloudbees.plugins.credentials.CredentialsProvider
import jenkins.model.Jenkins

def call() {
    echo "=== Credential Health Check (metadata only - secrets never logged) ==="

    def creds = CredentialsProvider.lookupCredentials(
        com.cloudbees.plugins.credentials.common.StandardCredentials.class,
        Jenkins.get(),
        null,
        null
    )

    def report = []

    for (def c in creds) {
        def status = "OK"
        // Only check expiration for certificate-based credentials
        if (c.metaClass.hasProperty(c, 'certificate')) {
            if (c.certificate?.expired) status = "EXPIRED"
        }
        report << [id: c.id, type: c.class.simpleName, status: status]
    }

    // Log metadata only - never the secret values
    echo "Credential health report: ${report}"

    // Safe call to audit endpoint (metadata only)
    try {
        def payload = groovy.json.JsonOutput.toJson([check: "credential-health", status: "completed", count: report.size(), timestamp: new Date().toString()])
        sh """
            curl -s -X POST -H 'Content-Type: application/json' \
                 -d '${payload}' \
                 https://jenkins-audit.internal/health
        """
    } catch (e) {
        echo "Warning: Could not reach audit endpoint: ${e.message}"
    }

    if (report.any { it.status == "EXPIRED" }) {
        error "Expired credentials detected. Please rotate them."
    }
}
