def call(Map config = [:]) {
    pipeline {
        agent any
        options { timeout(time: 1, unit: 'HOURS') }

        environment {
            VERSION = '0.0.0'
        }

        stages {
            stage('Checkout & Version Bump') {
                when { branch pattern: "main|release/*", comparator: "REGEXP" }
                steps {
                    script {
                        VERSION = bumpVersion()
                    }
                }
            }

            stage('Build & Sign') {
                steps {
                    sh './gradlew build' // or maven, npm, etc.
                    signArtifact("build/libs/*.jar")
                }
            }

            stage('Credential Health Check') {
                steps {
                    checkCredentialsHealth()
                }
            }

            stage('Deploy') {
                parallel {
                    stage('Dev') {
                        when { branch 'develop' }
                        steps { deployToKubernetes('dev', VERSION) }
                    }
                    stage('Staging') {
                        when { branch 'main' }
                        steps { deployToKubernetes('staging', VERSION) }
                    }
                    stage('Production') {
                        when { branch pattern: "release/*", comparator: "REGEXP" }
                        steps { deployToKubernetes('prod', VERSION) }
                    }
                }
            }

            stage('Canary Analysis') {
                when { branch 'main' }
                steps {
                    performCanaryAnalysis('prod', 10, 10)
                }
            }
        }

        post {
            success { echo "Pipeline succeeded for version ${VERSION}" }
            failure { echo "Pipeline failed" }
        }
    }
}
